from flask import Flask, request, jsonify, Response
from threading import Lock
from datetime import datetime
import os

app = Flask(__name__)
# Store queues and messages data in /workdir/data/
DATA_DIR = "/workdir/data/"
os.makedirs(DATA_DIR, exist_ok=True)

# In-memory storage for queues
# Structure: {queue_name: {"messages": [{"content": "..."}, ...]}}
queues_store = {}
# Lock for thread safety
lock = Lock()

# Status information
service_status = {
    "status": "running",
    "queues": []
}

def store_queue_data(queue_name, queue_data):
    """Store queue data in /workdir/data/ directory"""
    queue_path = os.path.join(DATA_DIR, f"{queue_name}.json")
    with open(queue_path, "w") as f:
        json.dump(queue_data, f)

def load_queue_data(queue_name):
    """Load queue data from file"""
    queue_path = os.path.join(DATA_DIR, f"{queue_name}.json")
    if os.path.exists(queue_path):
        with open(queue_path, "r") as f:
            return json.load(f)
    return None

def create_queue(name):
    """POST /queues - Create new queue"""
    global queues_store

    with lock:
        # Check if queue already exists
        if name in queues_store:
            return jsonify({"error": "Queue already exists"}), 409

        # Load existing data if any
        queue_data = {
            "name": name,
            "messages": [],
            "created_at": datetime.now().isoformat()
        }

        # Store in memory
        queues_store[name] = queue_data

        # Store file data
        store_queue_data(name, queue_data)

        return jsonify({
            "name": name,
            "status": "created",
            "message_count": 0
        }), 201

def send_message(queue_name, content):
    """POST /queues/{name}/messages - Send message"""
    global queues_store

    with lock:
        if queue_name not in queues_store:
            return jsonify({"error": "Queue not found"}), 404

        queue_data = queues_store[queue_name]

        # Create new message entry
        message = {
            "content": content,
            "received_at": datetime.now().isoformat(),
            "message_id": len(queue_data["messages"]) + 1
        }

        # Add to queue (FIFO - append to end)
        queue_data["messages"].append(message)
        queue_data["updated_at"] = datetime.now().isoformat()

        # Update in memory and file
        queues_store[queue_name] = queue_data
        store_queue_data(queue_name, queue_data)

        return jsonify({
            "message_id": message["message_id"],
            "content": content,
            "status": "sent"
        }), 201

def consume_message(queue_name):
    """GET /queues/{name}/messages - Receive/consume one message"""
    global queues_store

    with lock:
        if queue_name not in queues_store:
            return jsonify({"error": "Queue not found"}), 404

        queue_data = queues_store[queue_name]

        # Check if queue is empty
        if not queue_data.get("messages", []):
            return Response(status=204)

        # Get and remove first message (FIFO)
        message = queue_data["messages"].pop(0)

        # Update status
        queue_data["message_count"] = len(queue_data["messages"])
        queue_data["last_consumed_at"] = datetime.now().isoformat()

        # Update in memory and file
        queues_store[queue_name] = queue_data
        store_queue_data(queue_name, queue_data)

        return jsonify({
            "message_id": message["message_id"],
            "content": message["content"],
            "status": "consumed"
        }), 200

def get_status():
    """GET /status - Return basic service status"""
    with lock:
        return jsonify({
            "status": service_status["status"],
            "queues_count": len(queues_store),
            "message_count": sum(q.get("message_count", 0) for q in queues_store.values())
        }), 200

# Route definitions
@app.route("/queues", methods=["POST"])
def create_queue():
    """Create new queue"""
    data = request.get_json()

    if not data or "name" not in data:
        return jsonify({"error": "Missing required field: name"}), 400

    queue_name = data["name"]

    return create_queue(queue_name)

@app.route("/queues/{queue_name}/messages", methods=["POST"])
def send_message():
    """Send message to queue"""
    queue_name = request.path.split("/queues/")[1]

    # Extract content from request body
    data = request.get_json()

    if not data or "content" not in data:
        return jsonify({"error": "Missing required field: content"}), 400

    content = data["content"]

    return send_message(queue_name, content)

@app.route("/queues/{queue_name}/messages", methods=["GET"])
def consume_message():
    """Consume/receive one message from queue"""
    queue_name = request.path.split("/queues/")[1]

    return consume_message(queue_name)

@app.route("/status", methods=["GET"])
def get_status():
    """Return service status"""
    return get_status()

if __name__ == "__main__":
    # Start server on port 8000
    app.run(host="0.0.0.0", port=8000)
